def transform_rect(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    seen=[[False]*w for _ in range(h)]
    comps=[]
    def flood(i,j):
        c=g[i][j]; stack=[(i,j)]; cells=[]; seen[i][j]=True
        while stack:
            a,b=stack.pop(); cells.append((a,b))
            for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                x,y=a+di,b+dj
                if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==c:
                    seen[x][y]=True; stack.append((x,y))
        return cells
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                cells=flood(i,j)
                if len(cells)>1:
                    rs=[a for a,b in cells]; cs=[b for a,b in cells]
                    comps.append((g[i][j],min(rs),max(rs),min(cs),max(cs)))
    small=set()
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and len(flood(i,j))==1: small.add((i,j))
    res=[r[:] for r in g]
    for (i,j) in small:
        inside=[(c,(r1-r0+1)*(c1-c0+1)) for c,r0,r1,c0,c1 in comps if r0<=i<=r1 and c0<=j<=c1]
        if inside:
            res[i][j]=min(inside,key=lambda t:t[1])[0]
        else:
            nb=[g[x][y] for di,dj in((1,0),(-1,0),(0,1),(0,-1)) for x,y in[(i+di,j+dj)] if 0<=x<h and 0<=y<w]
            res[i][j]=Counter(nb).most_common(1)[0][0] if nb else Counter(x for r in g for x in r).most_common(1)[0][0]
    return res

