def color_comps(g, c, H, W):
    seen=set(); out=[]
    cells=[(i,j) for i in range(H) for j in range(W) if g[i,j]==c]
    for s in cells:
        if s in seen: continue
        stack=[s]; comp=[]
        while stack:
            x0,y0=stack.pop()
            if (x0,y0) in seen: continue
            seen.add((x0,y0)); comp.append((x0,y0))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                x,y=x0+dx,y0+dy
                if 0<=x<H and 0<=y<W and g[x,y]==c and (x,y) not in seen:
                    stack.append((x,y))
        out.append(comp)
    return out

def predict_r6(g, min_side=2, require_solid=False, ext=True):
    """noise = singleton same-color 4-component (color != bg).
    fill c if inside bbox of c-component possibly extended by noise-only rows/cols,
    extended rect >= min_side in each dim, all cells c-or-noise, >=1 c cell."""
    g=np.array(g); H,W=g.shape
    bg=int(Counter(g.flatten()).most_common(1)[0][0])
    # singleton comps of non-bg colors
    noise=[]
    for c in set(g.flatten())-{bg}:
        for comp in color_comps(g,int(c),H,W):
            if len(comp)==1: noise.append(comp[0])
    nset=set(noise)
    filled={}
    for c in set(g.flatten())-{bg}:
        c=int(c)
        for comp in color_comps(g,c,H,W):
            if len(comp)==1: continue
            r0=min(x for x,_ in comp); r1=max(x for x,_ in comp)
            c0=min(y for _,y in comp); c1=max(y for _,y in comp)
            if require_solid and len(comp)!=(r1-r0+1)*(c1-c0+1): continue
            lo_r, hi_r, lo_c, hi_c = r0, r1, c0, c1
            if ext:
                # extend by rows of pure c-or-noise above/below
                while lo_r-1>=0 and all(g[lo_r-1,y]==c or (lo_r-1,y) in nset for y in range(c0,c1+1)): lo_r-=1
                while hi_r+1<H  and all(g[hi_r+1,y]==c or (hi_r+1,y) in nset for y in range(c0,c1+1)): hi_r+=1
                while lo_c-1>=0 and all(g[x,lo_c-1]==c or (x,lo_c-1) in nset for x in range(r0,r1+1)): lo_c-=1
                while hi_c+1<W  and all(g[x,hi_c+1]==c or (x,hi_c+1) in nset for x in range(r0,r1+1)): hi_c+=1
            if (hi_r-lo_r+1)<min_side or (hi_c-lo_c+1)<min_side: continue
            for x in range(lo_r,hi_r+1):
                for y in range(lo_c,hi_c+1):
                    if (x,y) in nset: filled[(x,y)]=c
    out=[list(map(int,r)) for r in g]
    for (i,j) in nset: out[i][j]=filled.get((i,j),bg)
    return out, filled, bg, nset

